import{_ as a,o as t,c as o,a2 as d}from"./chunks/framework.D4up2k3b.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"ops/faq.md","filePath":"ops/faq.md","lastUpdated":null}'),r={name:"ops/faq.md"};function i(n,e,c,l,h,s){return t(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="侧栏没有-agent" tabindex="-1">侧栏没有 Agent？ <a class="header-anchor" href="#侧栏没有-agent" aria-label="Permalink to &quot;侧栏没有 Agent？&quot;">​</a></h2><ul><li>Agent 进程是否在跑、能否解析 Hub 主机名。</li><li>Hub URL 是否为 <code>https://</code>（或开发时显式 <code>FILEBOX_ALLOW_INSECURE_HUB=1</code>）。</li><li>token 是否与 Hub <code>--init-config</code> 打印的一致（Hub 只存 hash，对不上只能重新发 / 重新配）。</li><li>反代是否正确升级 WebSocket（<code>Upgrade</code> / <code>Connection</code>，见 <a href="./hub">Hub 运维</a>）。</li></ul><h2 id="有-agent-但文件列表空" tabindex="-1">有 Agent 但文件列表空？ <a class="header-anchor" href="#有-agent-但文件列表空" aria-label="Permalink to &quot;有 Agent 但文件列表空？&quot;">​</a></h2><p>需要在 <strong>Settings → Add Root</strong> 添加可读目录。无效路径会被拒绝且不破坏已有配置。见 <a href="/filebox/docs/guide/first-login">首次登录</a>。</p><h2 id="搜索很慢-被取消" tabindex="-1">搜索很慢 / 被取消？ <a class="header-anchor" href="#搜索很慢-被取消" aria-label="Permalink to &quot;搜索很慢 / 被取消？&quot;">​</a></h2><p>大树请收窄 root、加深忽略目录（如 <code>node_modules</code> / <code>venv</code>）、降低深度；可随时 Cancel。单 Agent 同时只跑一个搜索。</p><h2 id="打不开某些文件" tabindex="-1">打不开某些文件？ <a class="header-anchor" href="#打不开某些文件" aria-label="Permalink to &quot;打不开某些文件？&quot;">​</a></h2><p>敏感路径（<code>.ssh/</code>、<code>.env*</code>、<code>*.pem</code> 等）默认拒绝，即使在已授权 root 内。见 <a href="/filebox/docs/features/security">安全与敏感文件</a>。</p><h2 id="office-预览灰掉-失败" tabindex="-1">Office 预览灰掉 / 失败？ <a class="header-anchor" href="#office-预览灰掉-失败" aria-label="Permalink to &quot;Office 预览灰掉 / 失败？&quot;">​</a></h2><p>Agent 上是否配置了可用的 <code>soffice</code>？见 <a href="./office">Office 预览</a>。无 LibreOffice 时仍可 Download。</p><h2 id="terminal-要验证码" tabindex="-1">Terminal 要验证码？ <a class="header-anchor" href="#terminal-要验证码" aria-label="Permalink to &quot;Terminal 要验证码？&quot;">​</a></h2><p>必须在 Agent 本机完成 <code>./agent --setup-terminal-2fa</code>（或设置 <code>FILEBOX_AGENT_TERMINAL_TOTP_SECRET</code>）并重启。Hub 不保存密钥。见 <a href="/filebox/docs/features/terminal">远程终端</a>。</p><h2 id="演示页和真实-ui-不一样" tabindex="-1">演示页和真实 UI 不一样？ <a class="header-anchor" href="#演示页和真实-ui-不一样" aria-label="Permalink to &quot;演示页和真实 UI 不一样？&quot;">​</a></h2><p>演示是单页 mock，用于营销与布局预览：</p><table tabindex="0"><thead><tr><th>演示</th><th>真实应用</th></tr></thead><tbody><tr><td>无登录页</td><td>PoW + CSRF 登录</td></tr><tr><td>Search 替换主视图</td><td>Search 浮窗 / 底部 sheet</td></tr><tr><td>无独立 Explorer 页</td><td>有 Explorer 树视图</td></tr><tr><td>无 Settings / Audit</td><td>有 Add Root、登录审计等</td></tr></tbody></table><p>文档截图优先演示可复现视图，并逐步补真实机截图。</p><h2 id="开发联调" tabindex="-1">开发联调？ <a class="header-anchor" href="#开发联调" aria-label="Permalink to &quot;开发联调？&quot;">​</a></h2><p>见仓库 <a href="https://github.com/ZhimingYe/filebox/blob/main/docs/local-debugging.md" target="_blank" rel="noreferrer"><code>docs/local-debugging.md</code></a>（<code>FILEBOX_DEV_MODE=1</code> 等）。仓库根目录 <code>docs/</code> 是开发者 runbook，<strong>不</strong>并入本用户文档站。</p>',19)])])}const b=a(r,[["render",i]]);export{u as __pageData,b as default};
